static z_t1706_t z_t1705_Reader_create_owned(z_t1705_t* val) {
    z_t1706_t proto = {0};
    z_t1705_t* boxed = (z_t1705_t*)z_xmalloc(sizeof(z_t1705_t));
    *boxed = *val;
    proto.data = boxed;
    proto.vtable = &z_t1705_Reader_vtable;
    proto.destroy = z_t1705_Reader_owned_destroy;
    return proto;
}

